// ?setFlipRecursive@W3DTerrainBackground@@IAEXHHHH@Z
// partial score=0.4531 date=2026-09-28
// Scratch reconstruction for retail 0x007282A0..0x007285D5 (821 bytes).
// Caller, pin, and matched source establish the W3D member identity.
//
// MEASURED 2026-09-28 (build/scratch/loop.py, MSVC 7.1 /O2): 827 B compiled vs
// 821 B retail, 437 non-relocation byte differences, first at +2 (`sub esp,0x30`
// against retail's `sub esp,0x34`).  The x87 interpolation block (+0x160..+0x1f6),
// the four corner reads' bounds shape, the cliff index, the break tests and the
// three-calls-plus-tail-jump tail are byte-identical to retail modulo relocations;
// the whole residue is GPR allocation and the four-byte frame.
//
// Retail keeps `this` in EBP (spilled to [esp+0x40]) and limitX in EBX, and
// spills minX/j/minY/limitY/k; the /FAsc table here shows this build allocates
// limitX/this/i/j/minX/limitY in a 0x30 frame, one object short.  Retail's
// prologue is `push ebx/ebp/esi; mov ebp,ecx; push edi; mov [esp+0x40],ebp`.
// Frame slot tables for both sides are in build/scratch/*.cod.
//
// ALREADY TRIED, all byte-identical to this file (437) or worse -- do not redo:
// prologue statement order (10 permutations), corner-read order (all 24), loop
// counter roles/scopes, k/l hoisted to function scope, block-scoped locals,
// if-clamp vs ternary, postfix vs prefix loop counters, `m_map` member vs
// map() accessor, upstream-shaped WorldHeightMap/BfmeMaskAX classes with
// real member offsets (wReal, 727), extern g_bfmeDefaultBU for the 1.0f (breaks
// the x87 schedule), UnsignedShort corners (850 B), current-height read first,
// /G3 /G4 /G5 /G6 /G7 /Ga.  None moves the frame off 0x30.  The 4th parameter
// must stay `int`: the pinned thunk is HHHH, and a Real parameter mangles to
// ...HHHF@Z.
//
// 2026-09-28 session, +60 measured variants (build/scratch/v_[a-h].py, ~0.6 s
// each) and a 256-combination tools/shape_search.py run over six register /
// loop-head / clamp-spelling groups.  Still 437 at frame 0x30, ebp!=this.
// NEW: the frame size and this->EBP are NOT independent.  Every variant that
// reaches `sub esp,0x34` + `mov ebp,ecx` also has the full 12-slot retail map
// (0x13 match, 0x14 minX, 0x18 i, 0x1c minY, 0x20 C, 0x24 D, 0x28 B, 0x2c u,
// 0x30 A, 0x34 j, 0x38 limitY, 0x3c k, 0x40 this) and a byte-exact prologue
// through +0x10 -- but only by destroying an honest local.  The cheapest such
// spelling is `int l = yOrigin() + yOffset + j;` in place of `int l = minY + j;`
// (variant `minY_reexpr`: 821 B, frame 0x34, this-in-EBP, prologue byte-exact
// for 0x00..0x10) -- but it re-reads both members per inner iteration, so the
// loop body and the FPU schedule regress to 628 diffs.  Deleting the `minY`
// local is what buys the extra object, not adding one.
//
// Frame table for this bank (build/scratch/fa.py, /FAsc): 11 dwords, minY is
// absent -- it is register-allocated in EBX.  Retail homes minY AND k, and
// keeps limitX in EBX instead.  So retail holds 12 objects, this holds 11, and
// the allocator's only real choice is which of {minY, limitX, k} it spills.
// Reachability of 0x34 was confirmed with a forced-extra-object diagnostic, so
// the residue is a single allocator priority decision, not a missing local.
//
// 2026-09-28 also disproved, all at 437 with frame 0x30: inlined heightAt as
// one conjunction / nested ifs / const-pointer data / no null test (790 B);
// cliffAt as a conjunction or with the array read in a local; the four corners
// in their own block; whole-prologue block; minX/minY in a block or const;
// minX/minY or limitX/limitY or match declared in each order; `bool match`
// from a comparison; prologue and loop-head clamp groups, k/l split into
// separate clamped temps, k as the loop variable, k block-scoped, k/l
// accumulated (`k = k + t`), prefix/postfix counters, do/while inner loop,
// while-form outer loop (679 B, frame 0x1c), both loops in a block; a cached
// map pointer (815 B), a named `stride` local (435, the best of the session),
// a named float `tolerance` local, `raw`/`delta` as a fresh expression, const
// `u`/`v`, a `matched` local, an early `minY < 0` return, `width * 1 / 2`.
// Only the destructively-true `minY_reexpr` reaches 0x34, at a worse score.
//
// cl: /DNDEBUG /MD /EHsc

class BfmeMaskAX
{
public:
    void bfmeMarkAX(int x, int y, unsigned char value);
};

class Rva007282A0Map
{
public:
    int width(void) const
    {
        return *(const int *)((const char *)this + 0x08);
    }

    int height(void) const
    {
        return *(const int *)((const char *)this + 0x0c);
    }

    int count(void) const
    {
        return *(const int *)((const char *)this + 0x20);
    }

    unsigned short *heights(void) const
    {
        return *(unsigned short * const *)((const char *)this + 0x24);
    }

    int *cliffArray(void) const
    {
        return *(int * const *)((const char *)this + 0x94);
    }

    int drawOriginX(void) const
    {
        return *(const int *)((const char *)this + 0x120E0);
    }

    int drawOriginY(void) const
    {
        return *(const int *)((const char *)this + 0x120E4);
    }

    unsigned short heightAt(int x, int y) const
    {
        int index = y * width() + x;
        if (index < 0 || index >= count())
            return 0;
        unsigned short *data = heights();
        if (data == 0)
            return 0;
        return data[index];
    }

    bool cliffAt(int x, int y) const
    {
        int index = (drawOriginY() + y) * width() + drawOriginX() + x;
        if (index < 0)
            return false;
        if (index >= count())
            return false;
        return cliffArray()[index] != 0;
    }
};

class W3DTerrainBackground
{
protected:
    void setFlipRecursive(int xOffset, int yOffset, int width,
        int errorToleranceBits);

private:
    int xOrigin(void) const
    {
        return *(const int *)((const char *)this + 0x40);
    }

    int yOrigin(void) const
    {
        return *(const int *)((const char *)this + 0x44);
    }

    Rva007282A0Map *map(void) const
    {
        return *(Rva007282A0Map * const *)((const char *)this + 0x4c);
    }
};

// ?setFlipRecursive@W3DTerrainBackground@@IAEXHHHH@Z
void W3DTerrainBackground::setFlipRecursive(int xOffset, int yOffset, int width,
    int errorToleranceBits)
{

    int limitX = map()->width() - 1;
    int limitY = map()->height() - 1;
    bool match = true;
    int minX = xOrigin() + xOffset;
    int minY = yOrigin() + yOffset;
    int maxX = minX + width;
    if (maxX >= limitX)
        maxX = limitX;
    int maxY = minY + width;
    if (maxY >= limitY)
        maxY = limitY;

    int cornerA = map()->heightAt(minX, minY);
    int cornerB = map()->heightAt(maxX, minY);
    int cornerC = map()->heightAt(maxX, maxY);
    int cornerD = map()->heightAt(minX, maxY);

    int i;
    int j;
    for (i = 0; i <= width; ++i)
    {
        int k = minX + i;
        if (k >= limitX)
            k = limitX;
        for (j = 0; j <= width; ++j)
        {
            int l = minY + j;
            if (l >= limitY)
                l = limitY;

            if (map()->cliffAt(k, l))
            {
                match = false;
                break;
            }

            float u = (float)i / (float)width;
            float v = (float)j / (float)width;
            float predicted;
            if (v > (1.0f - u))
            {
                predicted = ((cornerB - cornerC) *
                    (1.0f - v) +
                    (cornerD - cornerC) *
                    (1.0f - u) + cornerC) *
                    0.0390625f;
            }
            else
            {
                predicted = ((cornerD - cornerA) * v +
                    (cornerB - cornerA) * u + cornerA) *
                    0.0390625f;
            }

            int currentHeight = map()->heightAt(k, l);
            float delta = predicted - currentHeight * 0.0390625f;
            if (delta < 0.0f)
                delta = -delta;
            if (delta > *(const float *)&errorToleranceBits)
            {
                match = false;
                break;
            }
        }
    }

    if (width == 1 || match)
    {
        int cornerMaxX = minX + width;
        if (cornerMaxX >= limitX)
            cornerMaxX = limitX;
        int cornerMaxY = minY + width;
        if (cornerMaxY >= limitY)
            cornerMaxY = limitY;

        ((BfmeMaskAX *)map())->bfmeMarkAX(minX, minY, 1);
        ((BfmeMaskAX *)map())->bfmeMarkAX(cornerMaxX, minY, 1);
        ((BfmeMaskAX *)map())->bfmeMarkAX(cornerMaxX, cornerMaxY, 1);
        ((BfmeMaskAX *)map())->bfmeMarkAX(minX, cornerMaxY, 1);
        return;
    }

    int halfWidth = width / 2;
    setFlipRecursive(xOffset, yOffset, halfWidth, errorToleranceBits);
    setFlipRecursive(xOffset, yOffset + halfWidth, halfWidth, errorToleranceBits);
    setFlipRecursive(xOffset + halfWidth, yOffset, halfWidth, errorToleranceBits);
    setFlipRecursive(xOffset + halfWidth, yOffset + halfWidth, halfWidth,
        errorToleranceBits);
}
